-- Schema as it existed before Flyway was introduced (generated by Hibernate).
-- Databases created by earlier versions of the app are marked as already at V1
-- (spring.flyway.baseline-on-migrate), so this only runs on an empty database.

CREATE TABLE users (
  id bigint NOT NULL AUTO_INCREMENT,
  name varchar(255) DEFAULT NULL,
  password varchar(255) NOT NULL,
  role varchar(255) NOT NULL,
  username varchar(255) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_users_username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE categories (
  id bigint NOT NULL AUTO_INCREMENT,
  name varchar(255) NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE payment_modes (
  id bigint NOT NULL AUTO_INCREMENT,
  name varchar(255) NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE reimbursement_types (
  id bigint NOT NULL AUTO_INCREMENT,
  name varchar(255) NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE expenses (
  id bigint NOT NULL AUTO_INCREMENT,
  amount decimal(12,2) NOT NULL,
  date date NOT NULL,
  tax_applicable bit(1) NOT NULL,
  category_id bigint NOT NULL,
  payment_mode_id bigint DEFAULT NULL,
  reimbursement_type_id bigint DEFAULT NULL,
  user_id bigint NOT NULL,
  description varchar(1000) DEFAULT NULL,
  attachment_content_type varchar(255) DEFAULT NULL,
  attachment_name varchar(255) DEFAULT NULL,
  attachment_path varchar(255) DEFAULT NULL,
  status varchar(255) NOT NULL,
  created_at datetime(6) NOT NULL,
  updated_at datetime(6) DEFAULT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_expenses_category FOREIGN KEY (category_id) REFERENCES categories (id),
  CONSTRAINT fk_expenses_payment_mode FOREIGN KEY (payment_mode_id) REFERENCES payment_modes (id),
  CONSTRAINT fk_expenses_reimbursement_type FOREIGN KEY (reimbursement_type_id) REFERENCES reimbursement_types (id),
  CONSTRAINT fk_expenses_user FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE expense_comments (
  id bigint NOT NULL AUTO_INCREMENT,
  expense_id bigint NOT NULL,
  user_id bigint NOT NULL,
  text varchar(1000) NOT NULL,
  created_at datetime(6) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_comments_expense FOREIGN KEY (expense_id) REFERENCES expenses (id),
  CONSTRAINT fk_comments_user FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
